Executar javascript:

(async function () {

    console.log('Você tem 5 segundos para abrir o dropdown...');

    await new Promise(r => setTimeout(r, 5000));

    const container =
        document.querySelector('.MuiAutocomplete-listbox') ||
        document.querySelector('[role="listbox"]');

    if (!container) {
        console.error('Container do dropdown não encontrado');
        return;
    }

    let ultimoScroll = -1;

    while (container.scrollTop !== ultimoScroll) {

        ultimoScroll = container.scrollTop;

        // Marca checkboxes visíveis
        document.querySelectorAll('input[type="checkbox"]').forEach(el => {
            if (!el.checked) {
                el.click();
            }
        });

        // Rola o dropdown
        container.scrollTop += 500;

        // Aguarda renderização
        await new Promise(r => setTimeout(r, 300));
    }

    // Última rodada
    document.querySelectorAll('input[type="checkbox"]').forEach(el => {
        if (!el.checked) {
            el.click();
        }
    });

    console.log('Todos selecionados');

})();
